input.content:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who browses books and places orders"

        bookshop = softwareSystem "Bookshop" "An online bookshop for browsing and ordering books" {
            webStore = container "Web Store" "The web application customers use to browse books and place orders" "Java / Spring Boot"
            orderProcessor = container "Order Processor" "Processes orders and coordinates fulfilment" "Python / Celery"

            customer -> webStore "Browses books and places orders through" "HTTPS"
            webStore -> orderProcessor "Submits new orders to" "AMQP"
        }
    }

    views {
        systemContext bookshop "SystemContext" "System context for the Bookshop" {
            include *
            autoLayout
            title "System Context for Bookshop"
        }
    }
}

